def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    strong_prev = []
    weak_prev = []

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 120:
                    strong_prev.append(float(bid))
                if float(bid) <= 40:
                    weak_prev.append(float(bid))

    if not alive:
        return float(min(budget, 1.0))

    expected_winners = max(1, int(supply // WATER_REQ))
    alive_count = len(alive)
    scarcity = alive_count - expected_winners

    urgent = (hp <= 3) or (no_water_days >= 2)
    semi_urgent = (hp <= 5) or (no_water_days >= 1)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    if urgent:
        bid = max(95.0, min(160.0, highest_prev + 6.0 if highest_prev > 0 else 110.0))
        if scarcity >= 2:
            bid = max(bid, 135.0)
        return float(min(budget, bid))

    if expected_winners >= alive_count:
        if weak_prev:
            bid = max(8.0, min(35.0, max(weak_prev) + 2.0))
        else:
            bid = 18.0
        if semi_urgent:
            bid = max(bid, 32.0)
        return float(min(budget, bid))

    if highest_prev >= 150.0 and hp >= 6 and no_water_days == 0:
        return float(min(budget, 12.0))

    if scarcity >= 2:
        if semi_urgent:
            bid = max(88.0, min(125.0, avg_prev * 0.72 + 8.0 if avg_prev > 0 else 92.0))
        else:
            bid = 20.0 if highest_prev >= 120.0 else 48.0
        return float(min(budget, bid))

    if highest_prev >= 120.0:
        if semi_urgent:
            bid = max(78.0, min(118.0, highest_prev * 0.7))
        else:
            bid = 28.0
    elif highest_prev > 0:
        bid = min(85.0, max(35.0, highest_prev + 3.0))
    else:
        bid = 42.0

    if day >= 8 and hp >= 6 and no_water_days == 0 and budget < DAILY_SALARY * 3:
        bid = min(bid, 25.0)

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']
    alive_opponents = {oid: opp for oid, opp in opponents_status.items() if opp['alive']}
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)
    prev_bids = []
    for opp in alive_opponents.values():
        trace = opp.get('previous_trace', {})
        if trace and 'bid' in trace and trace['bid'] is not None:
            prev_bids.append(trace['bid'])
    if hp <= 3 or no_water_days > 0:
        base = DAILY_SALARY * 0.95
    else:
        if prev_bids:
            max_prev = max(prev_bids)
            if max_prev <= DAILY_SALARY * 0.7:
                base = max_prev + 1.5
            else:
                base = DAILY_SALARY * 0.75
        else:
            base = DAILY_SALARY * 0.6
    bid = max(0, min(budget, base))
    if supply < 20 and hp > 3:
        bid = min(budget, bid * 1.1)
    return min(budget, max(0, bid))

