def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    supply = day_context['supply']
    num_slots = int(supply // WATER_REQ)

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.6

    if my_status['hp'] <= 2 or my_status['no_water_days'] > 0:
        base_bid = DAILY_SALARY * 0.95

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 3:
                base_bid = max(base_bid, DAILY_SALARY * 0.7)
            else:
                base_bid = max(base_bid, highest_prev_bid + 5)
        elif highest_prev_bid >= DAILY_SALARY * 0.5:
            base_bid = max(base_bid, highest_prev_bid + 2)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.45)

    if num_slots <= len(alive_opponents):
        if my_status['hp'] <= 4:
            base_bid = max(base_bid, DAILY_SALARY * 0.9)
        elif my_status['no_water_days'] > 0:
            base_bid = max(base_bid, DAILY_SALARY * 1.0)
        else:
            base_bid = max(base_bid, DAILY_SALARY * 0.75)

    final_bid = min(my_status['budget'], base_bid)

    return max(0.1, final_bid)
